import numpy as np
def comps(a,v):
    seen=set(); out=[]
    for r,c in zip(*np.where(a==v)):
        if (r,c) in seen: continue
        st=[(r,c)]; comp=set()
        while st:
            x,y=st.pop()
            if (x,y) in comp: continue
            comp.add((x,y))
            for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                p=(x+dx,y+dy)
                if 0<=p[0]<a.shape[0] and 0<=p[1]<a.shape[1] and a[p]==v: st.append(p)
        seen|=comp; out.append(comp)
    return out
